{
  "schemaVersion": "0.2",
  "slug": "flow-node",
  "name": "FlowNode",
  "family": "G",
  "status": "experimental",
  "purpose": "A positioned node card for flow diagrams with input and output ports.",
  "scenarios": [
    "Step in a workflow canvas",
    "Task in an automation graph",
    "State in a state machine view"
  ],
  "props": {
    "id": {
      "type": "string",
      "required": true,
      "description": "Stable node id."
    },
    "x": {
      "type": "number",
      "required": true,
      "description": "World x position in px."
    },
    "y": {
      "type": "number",
      "required": true,
      "description": "World y position in px."
    },
    "title": {
      "type": "string",
      "required": true,
      "description": "Node headline."
    },
    "status": {
      "type": "enum",
      "required": false,
      "description": "Node status tone.",
      "values": [
        "default",
        "active",
        "success",
        "failed"
      ],
      "default": "default"
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [
    {
      "name": "status",
      "values": [
        "default",
        "active",
        "success",
        "failed"
      ],
      "default": "default",
      "description": "Node status tone."
    }
  ],
  "states": [
    {
      "name": "default",
      "description": "Node rendered at its position."
    }
  ],
  "composition": {
    "allowedParents": [
      "canvas",
      "mind-map",
      "pipeline-view"
    ],
    "allowedChildren": [
      "text",
      "badge",
      "icon"
    ],
    "requiredContext": [
      "canvas"
    ]
  },
  "antiPatterns": [
    "Do not position flow nodes with physical left/right CSS.",
    "Do not render a flow node outside a canvas context."
  ],
  "a11y": {
    "role": "group",
    "keyboard": [],
    "focus": "Node is focusable when it carries actions.",
    "labeling": "Title labels the node; status has a text equivalent.",
    "wcag": [
      "1.3.1"
    ]
  },
  "responsive": {
    "strategy": "Fixed world size; scales with the canvas zoom.",
    "breakpoints": {
      "compact": "Scales with zoom.",
      "medium": "Scales with zoom.",
      "large": "Scales with zoom."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "supported"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. Direction inherits from document lang/dir.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "flow-node",
    "states": [
      "default",
      "active",
      "success",
      "failed"
    ],
    "intents": [
      "group-content"
    ]
  }
}

import './styles.css'

export interface FlowNodeProps {
  id: string
  x: number
  y: number
  title: string
  status?: 'default' | 'active' | 'success' | 'failed'
  /** Optional ARIA role (e.g. treeitem inside MindMap). */
  role?: 'treeitem'
  className?: string
}

export function FlowNode({ id, x, y, title, status = 'default', role, className }: FlowNodeProps) {
  const classes = ['cu-flow-node', 'cu-flow-node--' + status, className].filter(Boolean).join(' ')
  return (
    <div
      id={id}
      className={classes}
      role={role}
      aria-label={role ? title : undefined}
      data-ai-role="flow-node"
      data-ai-intent="group-content"
      data-ai-state={status}
      data-canvas-node
      style={{ transform: `translate(${x}px, ${y}px)` }}
    >
      <span className="cu-flow-node__port cu-flow-node__port--in" aria-hidden="true" />
      <span className="cu-flow-node__title">{title}</span>
      <span className="cu-flow-node__port cu-flow-node__port--out" aria-hidden="true" />
    </div>
  )
}

.cu-flow-node {
  position: absolute;
  inset-block-start: 0;
  inset-inline-start: 0;
  display: inline-flex;
  align-items: center;
  gap: var(--cu-space-1);
  padding-block: var(--cu-space-2);
  padding-inline: var(--cu-space-3);
  border: 1px solid var(--cu-color-border-default);
  border-radius: var(--cu-radius-md);
  background: var(--cu-color-background-default);
  color: var(--cu-color-fg-default);
  white-space: nowrap;
}

.cu-flow-node--active {
  border-color: var(--cu-color-palette-brand);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--cu-color-palette-brand) 40%, transparent);
}

.cu-flow-node--success {
  border-color: color-mix(in srgb, var(--cu-color-palette-brand) 50%, green);
}

.cu-flow-node--failed {
  border-color: color-mix(in srgb, var(--cu-color-palette-brand) 50%, red);
}

.cu-flow-node__port {
  inline-size: var(--cu-space-1);
  block-size: var(--cu-space-1);
  border-radius: 50%;
  background: var(--cu-color-palette-brand);
}
